// C/P Practice Test flashcards: original stand-alone cards that teach what the Chem/Phys questions of AAMC Practice
// Exams 1, 3, 4, 5 and 6 need (the pe1-cp … pe6-cp cards of data/qb-aamc-fl.js). TODAY's C/P flashcard step uses only
// these cards (masteryFlashPool in js/mastery.js).
// Every card names, in `from`, the Practice Exam card(s) whose question needs it; `aamc` and `disc` come from that card.
// Original wording, numbers and compounds only: no AAMC passage, question, number or answer choice is reproduced.
// Format: {id, s: topic tag, disc, aamc, q, choices: [4], ans: 0-3, exp, from: [src, …], how: {ask, know, steps, trap}, teach}
const CP_TEST_CARDS = [
  // ── Practice Exam 1 · Chem/Phys, Q1–10 ──
  // pe1-cp:1 (TLC on silica: the most polar compound moves least)
  {id:"cpt-pe1-01a",s:"Separations & Lab Techniques",disc:"organic_chem",aamc:"5C",skill:"SIRS 2",from:["pe1-cp:1#1"],
    q:"A silica gel TLC plate is developed with hexane containing a little diethyl ether. Which compound will travel the shortest distance up the plate?",
    choices:["Cyclohexanol","Cyclohexanone","Chlorocyclohexane","Cyclohexane"],ans:0,
    exp:"Silica is a **polar stationary phase**; the eluent is mostly nonpolar. A compound that can donate **hydrogen bonds** to silica's surface groups sticks most and moves least. Only cyclohexanol has an **O–H** donor; the ketone is only an acceptor, and the chloride and the alkane interact weakly.",
    how:{ask:"Decide which compound sticks hardest to the polar silica, so it moves least.",
      know:"• Normal-phase TLC: **polar stationary phase** (silica, Si–OH) and a less polar mobile phase.\n• More polar compound → held more by silica → **smaller Rf**.\n• Strength of the hold: **O–H/N–H donors** > C=O or ether O (acceptors) > C–halogen > C–H only.",
      steps:[{text:"The eluent is mostly hexane, so the polar silica holds polar compounds back.",hl:"hexane containing a little diethyl ether"},
        {text:"Rank each compound by its strongest interaction with Si–OH.",calc:["Cyclohexanol: **O–H donor** (hydrogen bonds)","Cyclohexanone: C=O acceptor only","Chlorocyclohexane: weak dipole","Cyclohexane: London forces only"]},
        {text:"The ketone, the chloride and the alkane interact less with silica, so they move farther.",strike:["Cyclohexanone","Chlorocyclohexane","Cyclohexane"]},
        {text:"Answer: cyclohexanol, the only hydrogen-bond donor, moves the shortest distance."}],
      trap:"Choosing the heaviest compound: in TLC, polarity decides how far a spot moves, not molar mass."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"silica gel",note:"polar stationary phase"},{t:"hexane",note:"nonpolar eluent"},{t:"shortest distance",note:"smallest Rf"}]},
      {text:"**Polar sticks to polar.** Silica is covered with Si–OH groups, so polar compounds cling to it and lag behind."},
      {text:"**Find the hydrogen-bond donor.** An O–H group can donate a hydrogen bond to Si–OH; a C=O can only accept one.",calc:["O–H > C=O > C–Cl > C–H"]},
      {text:"**Rule to reuse:** on silica, the compound with the strongest polar groups (O–H or N–H first) has the smallest Rf."}]},
  {id:"cpt-pe1-01b",s:"Separations & Lab Techniques",disc:"organic_chem",aamc:"5C",skill:"SIRS 2",from:["pe1-cp:1#1"],
    q:"In normal-phase TLC on silica, a spot with a very low Rf is interacting most strongly with which part of the system?",
    choices:["The polar silica","The nonpolar eluent","The solvent vapor","The glass backing"],ans:0,
    exp:"A spot moves only while it is dissolved in the **mobile phase**. A low Rf means it spends most of its time **adsorbed on the polar silica** (the stationary phase).",
    how:{ask:"Link a low Rf to the phase that holds the compound back.",
      know:"• **Rf** = distance moved by the spot ÷ distance moved by the solvent front.\n• The **stationary phase** (silica) holds compounds back; the **mobile phase** carries them up.\n• Low Rf → mostly bound to the stationary phase.",
      steps:[{text:"A low Rf means the spot barely moved compared with the solvent.",hl:"a very low Rf"},
        {text:"The eluent carries compounds up; a compound that liked it would move far, not barely move.",strike:["The nonpolar eluent"]},
        {text:"Vapor and the plate's backing do not take part in the separation.",strike:["The solvent vapor","The glass backing"]},
        {text:"Answer: the polar silica, the stationary phase."}],
      trap:"Thinking the eluent \"pulls\" a low-Rf spot: a strong attraction to the mobile phase gives a high Rf."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"normal-phase TLC",note:"polar stationary phase"},{t:"very low Rf",note:"barely moved"}]},
      {text:"**Two phases compete.** The silica holds the compound in place; the eluent carries it upward."},
      {text:"**Read the Rf.** A spot that barely moved spent almost all its time stuck to the silica.",calc:["low Rf → stationary phase wins","high Rf → mobile phase wins"]},
      {text:"**Rule to reuse:** a low Rf means strong binding to the stationary phase; a high Rf means the compound prefers the mobile phase."}]},
  {id:"cpt-pe1-01c",s:"Molecular Structure & Intermolecular Forces",disc:"organic_chem",aamc:"5C",skill:"SIRS 2",from:["pe1-cp:1#1"],
    q:"Which bond in a molecule allows it to donate a hydrogen bond to the Si–OH groups on a silica surface?",
    choices:["O–H","C=O","C–O–C","C–Br"],ans:0,
    exp:"A hydrogen-bond **donor** needs an H bonded to N, O or F. Only **O–H** has one. C=O and an ether oxygen (C–O–C) have lone pairs, so they can only **accept** hydrogen bonds; C–Br does neither well.",
    how:{ask:"Find the group with an H attached to N, O or F.",
      know:"• **Donor**: H covalently bonded to N, O or F (N–H, O–H, F–H).\n• **Acceptor**: a lone pair on N, O or F (C=O, ethers, amines).\n• A C–H or C–halogen bond is not a hydrogen-bond donor.",
      steps:[{text:"To donate, the molecule must supply an H on an electronegative atom.",hl:"donate a hydrogen bond"},
        {text:"C=O and an ether oxygen have lone pairs but no H on oxygen: acceptors only.",strike:["C=O","C–O–C"]},
        {text:"Bromine is not N, O or F, and the bond has no H.",strike:["C–Br"]},
        {text:"Answer: O–H."}],
      trap:"Counting C=O as a donor because it is polar: polarity alone does not make a donor; an H on N, O or F does."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"donate a hydrogen bond",note:"needs an H on N, O or F"},{t:"Si–OH",note:"the surface's own O–H groups"}]},
      {text:"**Donor = H on N, O or F.** The H is very δ+ and can reach a lone pair on another atom."},
      {text:"**Check each bond.**",calc:["O–H: donor ✓","C=O: acceptor only","C–O–C: acceptor only","C–Br: neither"]},
      {text:"**Rule to reuse:** only N–H, O–H and F–H donate hydrogen bonds; C=O and ether oxygens can only accept them."}]},
  {id:"cpt-pe1-01d",s:"Separations & Lab Techniques",disc:"organic_chem",aamc:"5C",skill:"SIRS 2",from:["pe1-cp:1#1"],
    q:"A student spots equal volumes of one compound on chromatography paper, once from a concentrated solution and once from a dilute one. After development, how do the two spots compare?",
    choices:["Same Rf; bigger concentrated spot","Same Rf; bigger dilute spot","Higher Rf; bigger concentrated spot","Lower Rf; same spot size"],ans:0,
    exp:"How far a compound travels depends on how it divides between the stationary and mobile phases, which is a property of the compound, so both spots have the **same Rf**. Concentration only changes **how much** material is there, so the concentrated spot is **larger and darker**.",
    how:{ask:"Separate what sets the distance a compound moves from what sets the size of its spot.",
      know:"• Distance moved (Rf) is set by how strongly the compound binds the stationary phase compared with the mobile phase.\n• **Spot size** is set by the **amount** applied (concentration), not by the distance moved.",
      steps:[{text:"It is the same compound on the same paper and solvent.",hl:"spots equal volumes of one compound"},
        {text:"Same compound, same phases → same Rf, so a change in Rf is ruled out.",strike:["Higher Rf; bigger concentrated spot","Lower Rf; same spot size"]},
        {text:"More material in the concentrated sample makes its spot the larger one.",strike:["Same Rf; bigger dilute spot"]},
        {text:"Answer: same Rf; the concentrated spot is bigger."}],
      trap:"Thinking a stronger solution moves farther: concentration changes how much is there, not how far it travels."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"equal volumes of one compound",note:"same Rf expected"},{t:"concentrated",note:"more material"},{t:"dilute",note:"less material"}]},
      {text:"**Distance is a property of the compound.** It depends on how the compound shares itself between the paper's water and the solvent."},
      {text:"**Size is a property of the amount.** More material spreads into a bigger, darker spot.",calc:["Rf: same","spot size: concentrated > dilute"]},
      {text:"**Rule to reuse:** in chromatography, Rf is characteristic of the compound under fixed conditions; spot size only reflects how much was applied."}]},
  // pe1-cp:2 (the assumption behind a prebiotic-origin claim)
  {id:"cpt-pe1-02a",s:"Research Design & Reasoning",disc:"organic_chem",aamc:"5C",skill:"SIRS 3",from:["pe1-cp:2#1"],
    q:"A team concludes that amino acids arose on the primitive Earth, since passing sparks through methane and ammonia gave them in the lab. The argument requires that:",
    choices:["those gases were present then.","the yield exceeded half the methane.","the products were optically pure.","sparks speed up every reaction."],ans:0,
    exp:"A lab synthesis shows what **can** happen. To conclude it **did** happen on the early Earth, the **starting materials and conditions** (here methane, ammonia and electrical discharge) must have existed then. Yield, purity and a claim about all reactions do not bear on that.",
    how:{ask:"Find the unstated premise that must be true for the lab result to support the historical claim.",
      know:"• **Assumption**: a premise the conclusion needs but does not state; if it were false, the conclusion would fail.\n• A lab model of a past event supports the claim only if its **inputs and conditions** existed at that time.",
      steps:[{text:"The conclusion is about the early Earth; the evidence is from a lab.",hl:"amino acids arose on the primitive Earth"},
        {text:"Test each choice: if it were false, would the argument fail?",calc:["gases absent then → the lab result says nothing about then → fails","low yield → some still formed → stands"]},
        {text:"Yield, optical purity and all reactions are not needed for the conclusion.",strike:["the yield exceeded half the methane.","the products were optically pure.","sparks speed up every reaction."]},
        {text:"Answer: the gases must have been present on the early Earth."}],
      trap:"Choosing a detail about the experiment's quality; the gap is between the lab and the early Earth."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"on the primitive Earth",note:"the conclusion"},{t:"in the lab",note:"the evidence"},{t:"requires",note:"find the assumption"}]},
      {text:"**Split conclusion from evidence.** The evidence is a lab result; the conclusion is about the past."},
      {text:"**Bridge the gap.** For the lab to stand in for the early Earth, the same ingredients had to be there."},
      {text:"**Negate to test.** If the gases were absent, the argument collapses, so that is the assumption.",calc:["negate the choice → does the conclusion fail?"]},
      {text:"**Rule to reuse:** a lab model supports a claim about the past only if its starting materials and conditions existed then."}]},
  {id:"cpt-pe1-02b",s:"Research Design & Reasoning",disc:"organic_chem",aamc:"5C",skill:"SIRS 3",from:["pe1-cp:2#1"],
    q:"An unstated premise that must be true for a study's conclusion to hold is called:",
    choices:["an assumption","a confounding factor","a dependent variable","a null result"],ans:0,
    exp:"An **assumption** is a premise the argument needs but never states. A confounding factor is a third variable that distorts a relationship; a dependent variable is what is measured; a null result is a finding of no effect.",
    how:{ask:"Match the definition to the term for an unstated, required premise.",
      know:"• **Assumption**: unstated premise the conclusion depends on.\n• **Confounder**: a third variable linked to both cause and effect.\n• **Dependent variable**: the measured outcome.\n• **Null result**: no effect detected.",
      steps:[{text:"The definition stresses \"unstated\" and \"must be true\".",hl:"An unstated premise that must be true"},
        {text:"A confounder, a measured outcome and a no-effect finding are parts of a study's design or results, not hidden premises.",strike:["a confounding factor","a dependent variable","a null result"]},
        {text:"Answer: an assumption."}],
      trap:"Picking a confounding factor because it is also \"hidden\"; a confounder is a variable, not a premise of the argument."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"unstated premise",note:"not said aloud"},{t:"must be true",note:"needed by the conclusion"}]},
      {text:"**An argument has parts:** evidence, conclusion and the unstated links between them."},
      {text:"**Name the link.** The unstated link that must hold is the assumption; negate it and the conclusion falls."},
      {text:"**Rule to reuse:** an assumption is the unstated premise whose denial would break the conclusion."}]},
  // pe1-cp:3 (Rf measured from the baseline)
  {id:"cpt-pe1-03a",s:"Separations & Lab Techniques",disc:"organic_chem",aamc:"5C",skill:"SIRS 4",from:["pe1-cp:3#1"],
    q:"A TLC baseline is 1.5 cm above the plate's lower edge. Measured from that edge, the solvent front is at 9.5 cm and a spot's center is at 5.5 cm. What is the retention factor (Rf)?",
    choices:["0.42","0.50","0.58","2.0"],ans:1,
    exp:"**Rf = spot distance ÷ solvent-front distance, both from the baseline.** Spot: 5.5 − 1.5 = 4.0 cm. Front: 9.5 − 1.5 = 8.0 cm. Rf = 4.0 ÷ 8.0 = **0.50**.",
    how:{ask:"Measure both distances from the baseline, then divide.",
      know:"**Rf = distance moved by the compound ÷ distance moved by the solvent front**, both measured from the **baseline** where the sample was spotted. Rf is between 0 and 1.",
      steps:[{text:"The distances are given from the edge, but the sample started at the baseline.",hl:"baseline is 1.5 cm above the plate's lower edge",fig:"cpt-tlc-plate"},
        {text:"Subtract the baseline from both readings.",calc:["spot: 5.5 − 1.5 = **4.0 cm**","front: 9.5 − 1.5 = **8.0 cm**"]},
        {text:"Divide.",calc:["Rf = 4.0 ÷ 8.0 = **0.50**"]},
        {text:"0.58 skips the baseline (5.5 ÷ 9.5), 0.42 subtracts it from only the spot, and 2.0 is inverted.",strike:["0.58","0.42","2.0"]},
        {text:"Answer: 0.50."}],
      trap:"Dividing the raw readings (5.5 ÷ 9.5 = 0.58): both distances must start at the baseline."},
    teach:[{text:"First, **find every number** and what it means.",marks:[{t:"1.5 cm",note:"where the sample started"},{t:"9.5 cm",note:"solvent front, from the edge"},{t:"5.5 cm",note:"spot, from the edge"}]},
      {text:"**Start at the baseline.** The race starts where the sample was spotted, not at the plate's edge.",calc:["spot: 5.5 − 1.5 = 4.0 cm","front: 9.5 − 1.5 = 8.0 cm"]},
      {text:"**Divide spot by front.**",calc:["Rf = 4.0 ÷ 8.0 = 0.50"]},
      {text:"**Rule to reuse:** Rf = (spot − baseline) ÷ (front − baseline), and it always falls between 0 and 1."}]},
  {id:"cpt-pe1-03b",s:"Separations & Lab Techniques",disc:"organic_chem",aamc:"5C",skill:"SIRS 4",from:["pe1-cp:3#1"],
    q:"A student reports an Rf value for a TLC spot. Within what range must any correctly calculated Rf fall?",
    choices:["0 to 1","1 to 10","−1 to 1","0 to 100"],ans:0,
    exp:"A spot can never travel farther than the solvent front that carries it, and it cannot move backward. So **Rf = spot distance ÷ front distance** lies **between 0 and 1**. A value above 1 means the distances were swapped or mismeasured.",
    how:{ask:"Use the definition of Rf to bound its value.",
      know:"**Rf = spot distance ÷ solvent-front distance.** The spot moves no farther than the front (≤ 1) and not below the baseline (≥ 0).",
      steps:[{text:"The spot is carried by the solvent, so it cannot pass the front.",hl:"correctly calculated Rf"},
        {text:"Distances are never negative, and the ratio never exceeds 1.",strike:["−1 to 1","1 to 10","0 to 100"]},
        {text:"Answer: 0 to 1."}],
      trap:"Reading Rf as a percent (0 to 100); it is a plain ratio."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"Rf value",note:"a ratio of two distances"}]},
      {text:"**Top of the ratio ≤ bottom.** The spot rides on the solvent, so it never goes past the front."},
      {text:"**Bottom limit.** A spot that never left the baseline has Rf = 0.",calc:["0 ≤ Rf ≤ 1"]},
      {text:"**Rule to reuse:** every Rf lies between 0 and 1; a larger value means the ratio is inverted."}]},
  // pe1-cp:4 (E1 dehydration: which alkenes form directly from the carbocation)
  {id:"cpt-pe1-04a",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5C",skill:"SIRS 4",from:["pe1-cp:4#1"],
    q:"In the E1 dehydration of an alcohol, the proton removed in the final step comes from:",
    choices:["an adjacent carbon.","the cationic carbon.","any carbon in the chain.","the departing water."],ans:0,
    exp:"In E1, water leaves to give a carbocation; a base then removes an **H⁺ from a carbon bonded to C⁺**. The new **C=C** forms between those two neighboring carbons, so the double bond always touches the former cationic carbon.",
    how:{ask:"Locate the H that leaves so the new C=C can form.",
      know:"• **E1**: protonate –OH → water leaves → **carbocation** → base removes an H⁺ from a **neighboring (β) carbon**.\n• The new C=C joins the cationic carbon and that neighbor.",
      steps:[{text:"The last step makes the C=C, which needs electrons from a C–H bond next to C⁺.",hl:"the final step",fig:"cpt-e1-beta"},
        {text:"Losing H⁺ from C⁺ itself would not create a C=C, and an H two or more carbons away cannot form a C=C to C⁺ in one step.",strike:["the cationic carbon.","any carbon in the chain."]},
        {text:"Water has already left; it is not the source of the eliminated H⁺.",strike:["the departing water."]},
        {text:"Answer: an adjacent carbon."}],
      trap:"Thinking any H in the molecule can leave; only an H on a carbon next to C⁺ gives a C=C in one step."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"E1 dehydration",note:"carbocation path"},{t:"final step",note:"loss of H⁺"}]},
      {text:"**Make the cation.** Acid protonates –OH; water leaves; C⁺ forms where the OH was."},
      {text:"**Form the C=C.** The electrons of a C–H bond on the next carbon swing in to make the double bond.",calc:["H–C–C⁺ → C=C + H⁺"]},
      {text:"**Rule to reuse:** in E1, the C=C always forms between the cationic carbon and a carbon directly bonded to it."}]},
  {id:"cpt-pe1-04b",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5C",skill:"SIRS 4",from:["pe1-cp:4#1"],
    q:"3-Methylpentan-3-ol is heated with concentrated H₂SO₄. Which alkene is NOT formed directly from the carbocation?",
    choices:["(E)-3-Methylpent-2-ene","(Z)-3-Methylpent-2-ene","2-Ethylbut-1-ene","3-Methylpent-1-ene"],ans:3,
    exp:"Water leaves C3, giving a **tertiary cation at C3**. Its neighbors are C2, C4 (each in an ethyl group) and the methyl carbon. Loss of H⁺ from C2 or C4 gives 3-methylpent-2-ene, as **both E and Z** because the cation is planar; loss from the methyl gives 2-ethylbut-1-ene. **3-Methylpent-1-ene** has its C=C between C1 and C2, which does not touch C3, so it cannot form directly.",
    how:{ask:"List the carbons next to the cationic carbon; every direct alkene has its C=C touching C⁺.",
      know:"• E1: C⁺ forms where the OH was; the C=C forms between C⁺ and a **neighboring carbon** that loses H⁺.\n• The planar cation gives **both E and Z** isomers when the alkene can have them.\n• An alkene whose C=C does not include the old C–OH carbon needs a rearrangement first.",
      steps:[{text:"The OH is on C3, a tertiary carbon, so C⁺ forms at C3.",hl:"3-Methylpentan-3-ol"},
        {text:"Neighbors of C3 and the alkene each gives.",fig:"cpt-e1-cation",calc:["C2 or C4 → C=C at C2–C3: **3-methylpent-2-ene (E and Z)**","CH₃ on C3 → C=CH₂: **2-ethylbut-1-ene**"]},
        {text:"These three put the C=C on C3, so they form directly.",strike:["(E)-3-Methylpent-2-ene","(Z)-3-Methylpent-2-ene","2-Ethylbut-1-ene"]},
        {text:"Answer: 3-methylpent-1-ene; its C=C (C1–C2) does not include C3."}],
      trap:"Ruling out one of the E/Z pair: a planar cation can lose either neighboring H, so both geometric isomers form."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"3-Methylpentan-3-ol",note:"OH on a 3° carbon"},{t:"H₂SO₄",note:"acid, heat: E1"},{t:"NOT formed directly",note:"find the odd alkene"}]},
      {text:"**Place the cation.** C⁺ sits on C3, where the OH was."},
      {text:"**Walk to each neighbor.** Each neighboring C–H can become the second carbon of the C=C.",calc:["C2/C4 → pent-2-ene (E and Z)","CH₃ → but-1-ene with an ethyl branch"]},
      {text:"**Spot the outsider.** A C=C at C1–C2 never touches C3.",calc:["3-methylpent-1-ene ✗"]},
      {text:"**Rule to reuse:** a direct E1 alkene always has the former C–OH carbon in its C=C."}]},
  {id:"cpt-pe1-04c",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5C",skill:"SIRS 4",from:["pe1-cp:4#4"],
    q:"Why does the acid-catalyzed dehydration of a tertiary alcohol often give both the E and the Z alkene?",
    choices:["The cation is planar","The alcohol is chiral","Water is a strong base","The acid adds twice"],ans:0,
    exp:"The carbocation is **sp² and planar**, and the C–C bond to it can rotate. Rotation about the bond to C⁺ lets either H on the neighboring carbon line up with the empty p orbital, so the C=C can form with the groups on the **same side (Z)** or **opposite sides (E)**. Both isomers form; the more stable one is major.",
    how:{ask:"Explain why the intermediate does not fix the alkene's geometry.",
      know:"• A carbocation is **sp², trigonal planar**.\n• Rotation about the bond to C⁺ lets either neighboring H line up to leave.\n• So E1 gives **both E and Z** alkenes (E usually major).",
      steps:[{text:"Both isomers come from the same carbocation.",hl:"both the E and the Z alkene"},
        {text:"Chirality of the alcohol is lost once the planar cation forms; water is a weak base; the acid is a catalyst.",strike:["The alcohol is chiral","Water is a strong base","The acid adds twice"]},
        {text:"Answer: the cation is planar."}],
      trap:"Thinking E1 is stereospecific like E2; E1 passes through a flat cation, so geometry is not controlled."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"tertiary alcohol",note:"E1 via a cation"},{t:"E and the Z",note:"two geometries"}]},
      {text:"**Picture the cation.** C⁺ is flat, with its three groups in one plane."},
      {text:"**Either H can leave.** Rotation puts one H or another in line, so the groups end up on the same or opposite sides.",calc:["same side → Z","opposite sides → E"]},
      {text:"**Rule to reuse:** E1 through a planar carbocation gives both E and Z alkenes, with the more stable E usually major."}]},
  {id:"cpt-pe1-04d",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5C",skill:"SIRS 4",from:["pe1-cp:4#2"],
    q:"Each alcohol is warmed with the same concentrated acid. Which one dehydrates fastest?",
    choices:["2-Methylbutan-2-ol","Pentan-1-ol","Pentan-2-ol","3-Methylbutan-1-ol"],ans:0,
    exp:"Acid-catalyzed dehydration goes by **E1**: the slow step is water leaving to form a **carbocation**. The more stable the cation, the faster it forms: **3° > 2° > 1°**. 2-Methylbutan-2-ol has its OH on a tertiary carbon, so it dehydrates fastest; pentan-2-ol (2°) is slower, and the two primary alcohols are slowest.",
    how:{ask:"Classify each alcohol's OH carbon, then rank by the stability of the carbocation it would form.",
      know:"• E1 dehydration: protonate –OH → water leaves (**slow step**) → carbocation → lose H⁺.\n• A faster slow step means a more stable cation: **3° > 2° > 1°**.\n• Classify by counting carbons bonded to the C–OH carbon: 3 = tertiary, 2 = secondary, 1 = primary.",
      steps:[{text:"Same acid, same temperature: only the alcohol's structure changes the rate.",hl:"the same concentrated acid"},
        {text:"Classify each OH carbon.",calc:["2-methylbutan-2-ol: C2 bonded to 3 carbons → **3°**","pentan-2-ol: **2°**","pentan-1-ol and 3-methylbutan-1-ol: **1°**"]},
        {text:"Primary alcohols would have to form an unstable 1° cation, so they are slowest.",strike:["Pentan-1-ol","3-Methylbutan-1-ol"]},
        {text:"A 2° cation forms more slowly than a 3° cation.",strike:["Pentan-2-ol"]},
        {text:"Answer: 2-methylbutan-2-ol, the tertiary alcohol."}],
      trap:"Ranking by branching anywhere in the chain: 3-methylbutan-1-ol is branched, but its OH is on a primary carbon."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"same concentrated acid",note:"only structure differs"},{t:"dehydrates fastest",note:"easiest carbocation"}]},
      {text:"**Find the slow step.** In E1 dehydration, water leaving to make the carbocation sets the rate."},
      {text:"**Rank the cations.** More alkyl groups on C⁺ stabilize it.",calc:["3° > 2° > 1°"]},
      {text:"**Classify the OH carbon.** Count its carbon neighbors; 2-methylbutan-2-ol has three."},
      {text:"**Rule to reuse:** tertiary alcohols dehydrate most easily because they form the most stable carbocation; primary alcohols dehydrate slowest."}]},
  {id:"cpt-pe1-04e",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5C",skill:"SIRS 4",from:["pe1-cp:4#1","pe1-cp:4#3","pe1-cp:4#4"],
    q:"Which statement about the acid-catalyzed dehydration of 1-methylcyclopentanol is true?",
    choices:["One water is lost, via a carbocation","Two waters are lost in one step","The alkene geometry is set by the alcohol","The C–H bond breaks before the C–O bond"],ans:0,
    exp:"The OH is protonated and leaves as **one water molecule**, giving a **planar carbocation**; then H⁺ is lost from a neighboring carbon. Because the flat cation forgets the alcohol's 3D arrangement, the reaction is **not stereospecific**, and the C–O bond breaks first (it is E1, not a concerted E2).",
    how:{ask:"Judge each statement against the E1 mechanism: what leaves, in what order, through what intermediate.",
      know:"• **E1 dehydration**: ROH + H⁺ → ROH₂⁺ → **R⁺ + H₂O** (one water) → alkene + H⁺.\n• The C–O bond breaks **first**; the C–H bond breaks last.\n• The carbocation is planar, so the alcohol's geometry is lost: **not stereospecific**.",
      steps:[{text:"Write the E1 steps for this tertiary alcohol.",hl:"acid-catalyzed dehydration",calc:["R–OH + H⁺ → R–OH₂⁺","R–OH₂⁺ → **R⁺ + H₂O**","R⁺ → alkene + H⁺"]},
        {text:"Only one water molecule leaves, and the steps are separate, not one concerted step.",strike:["Two waters are lost in one step"]},
        {text:"The planar cation does not remember the alcohol's arrangement, so the alcohol does not set the geometry.",strike:["The alkene geometry is set by the alcohol"]},
        {text:"Water leaves before H⁺ is removed, so the C–O bond breaks first.",strike:["The C–H bond breaks before the C–O bond"]},
        {text:"Answer: one water is lost, via a carbocation."}],
      trap:"Treating dehydration like E2 (one step, stereospecific): with acid and heat, alcohols go through a carbocation."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"acid-catalyzed dehydration",note:"E1"},{t:"1-methylcyclopentanol",note:"tertiary alcohol"}]},
      {text:"**Count the waters.** One OH leaves as one H₂O."},
      {text:"**Order the bonds.** C–O breaks to make C⁺; the C–H breaks after.",calc:["C–O first → C⁺ → C–H last"]},
      {text:"**Flat cation, no memory.** The planar C⁺ can lose an H from either side, so the starting geometry does not carry over."},
      {text:"**Rule to reuse:** acid-catalyzed dehydration loses one water through a carbocation, so it is stepwise and not stereospecific."}]},
  // pe1-cp:5 (activated carboxyl + amine → amide; amide C=O in the IR)
  {id:"cpt-pe1-05a",s:"Amino Acids & Proteins",disc:"organic_chem",aamc:"5C",skill:"SIRS 1",from:["pe1-cp:5#1"],
    q:"The activated carboxyl group of glycine reacts with the amino group of valine, releasing one water molecule. Which linkage forms?",
    choices:["Amide","Ester","Anhydride","Ether"],ans:0,
    exp:"Carboxyl + **amine** → **amide** (a peptide bond), with loss of H₂O. Carboxyl + alcohol gives an ester; carboxyl + carboxyl gives an anhydride; an ether needs two alcohols.",
    how:{ask:"Name the bond made when a carboxyl group condenses with an amine.",
      know:"• **Condensation** joins two groups and releases H₂O.\n• RCOOH + R′NH₂ → **amide** (RCONHR′); RCOOH + R′OH → ester; RCOOH + RCOOH → anhydride.\n• Between amino acids the amide is the **peptide bond**.",
      steps:[{text:"The partner is the amino group, an amine.",hl:"amino group of valine"},
        {text:"Ester and ether need an alcohol O; an anhydride needs a second carboxyl group.",strike:["Ester","Ether","Anhydride"]},
        {text:"Answer: an amide (peptide) bond."}],
      trap:"Choosing ester because water is lost; esters also lose water, but only when the partner is an alcohol."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"carboxyl group",note:"acyl donor"},{t:"amino group",note:"N nucleophile"},{t:"releasing one water",note:"condensation"}]},
      {text:"**Match the partner.** The nucleophile here is nitrogen, from the amine."},
      {text:"**Build the bond.**",calc:["R–COOH + H₂N–R′ → R–CO–NH–R′ + H₂O"]},
      {text:"**Rule to reuse:** carboxyl + amine → amide (peptide bond); carboxyl + alcohol → ester."}]},
  // pe1-cp:6 (SN2 rate: steric crowding at and next to the reacting carbon)
  {id:"cpt-pe1-06a",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5D",skill:"SIRS 2",from:["pe1-cp:6#1"],
    q:"Which statement gives the order of SN2 reaction rates for alkyl halides with the same leaving group?",
    choices:["Methyl fastest, tertiary slowest","Tertiary fastest, methyl slowest","Secondary fastest, methyl slowest","Primary fastest, tertiary slowest"],ans:0,
    exp:"SN2 needs **backside attack** on the carbon bearing the leaving group. Each added alkyl group crowds that side: **methyl > 1° > 2° ≫ 3°** (tertiary essentially does not react by SN2).",
    how:{ask:"Rank substrates by how crowded the backside of the reacting carbon is.",
      know:"• **SN2**: one step, the nucleophile attacks opposite the leaving group.\n• Steric order: **methyl > primary > secondary ≫ tertiary**.\n• The reverse order (3° fastest) belongs to SN1, which goes through a carbocation.",
      steps:[{text:"SN2 rate depends on access to the carbon's backside.",hl:"order of SN2 reaction rates",fig:"cpt-sn2-backside"},
        {text:"Tertiary-first is the SN1 order; secondary-first fits neither.",strike:["Tertiary fastest, methyl slowest","Secondary fastest, methyl slowest"]},
        {text:"Primary is fast but methyl, with no alkyl groups, is faster still.",strike:["Primary fastest, tertiary slowest"]},
        {text:"Answer: methyl fastest, tertiary slowest."}],
      trap:"Using carbocation stability (3° > 2° > 1°); that ranks SN1 rates, not SN2."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"SN2",note:"backside attack, one step"},{t:"same leaving group",note:"only sterics differ"}]},
      {text:"**Picture the attack.** The nucleophile must reach the carbon from behind the leaving group."},
      {text:"**Count the blockers.** Each alkyl group on that carbon gets in the way.",calc:["CH₃–X: 0 → fastest","1°: 1","2°: 2","3°: 3 → no SN2"]},
      {text:"**Rule to reuse:** SN2 rates run methyl > 1° > 2° ≫ 3°, the reverse of SN1."}]},
  {id:"cpt-pe1-06d",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5D",skill:"SIRS 2",from:["pe1-cp:6#1"],
    q:"With HBr, a secondary alcohol substitutes more slowly than a primary alcohol by SN2. Where is the crowding that slows the secondary alcohol?",
    choices:["At the OH-bearing carbon","At the protonated oxygen","At the incoming bromide","At the solvent molecules"],ans:0,
    exp:"In SN2, Br⁻ attacks the **carbon bonded to the leaving group** (–OH₂⁺) from the back side. A secondary carbon carries two alkyl groups that crowd that back side; a primary carbon carries one. The oxygen is the leaving group, on the other side, so crowding there does not matter.",
    how:{ask:"Find the atom the nucleophile attacks, then see what crowds it.",
      know:"• SN2: the nucleophile attacks the **carbon** that holds the leaving group, from the side opposite it.\n• Groups on **that carbon** block the attack, so the SN2 rate is methyl > 1° > 2°, and 3° does not react by SN2.\n• With an alcohol and HX, the leaving group is –OH₂⁺; the oxygen is not attacked.",
      steps:[{text:"The nucleophile is Br⁻; the leaving group is water on the protonated alcohol.",hl:"secondary alcohol substitutes more slowly",fig:"cpt-sn2-crowded"},
        {text:"Br⁻ bonds to carbon, not oxygen, so the oxygen's surroundings do not set the rate.",strike:["At the protonated oxygen"]},
        {text:"The nucleophile and solvent are the same for both alcohols, so they cannot explain the difference.",strike:["At the incoming bromide","At the solvent molecules"]},
        {text:"Answer: at the carbon bearing the OH, which has two alkyl groups in a secondary alcohol."}],
      trap:"Looking at the oxygen because the –OH is the group that changes: SN2 attack, and its crowding, happen at the carbon."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"secondary alcohol",note:"two alkyl groups on C–OH"},{t:"SN2",note:"backside attack on carbon"}]},
      {text:"**Find the target.** In SN2 the nucleophile attacks the carbon that holds the leaving group."},
      {text:"**Count the blockers on that carbon.**",calc:["1° carbon: 1 alkyl group","2° carbon: 2 alkyl groups → slower","3° carbon: 3 → no SN2"]},
      {text:"**Rule to reuse:** SN2 slows with crowding at the carbon being attacked (methyl > 1° > 2°, no 3°), not at the leaving group."}]},
  // pe1-cp:7 (carbocation rearrangement in alcohol + HX)
  {id:"cpt-pe1-07a",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5D",skill:"SIRS 2",from:["pe1-cp:7#1"],
    q:"During the reaction of an alcohol with HBr, a secondary carbocation shifts a hydride from the next carbon to become tertiary. Why does this shift occur?",
    choices:["The 3° cation is more stable","The 2° cation is more stable","Hydride is a good leaving group","Bromide prefers 2° carbons"],ans:0,
    exp:"Alkyl groups **donate electron density** (hyperconjugation and induction) to C⁺, so **3° > 2° > 1°** in stability. A 1,2-hydride shift moves the + charge to the neighboring carbon when that carbon becomes a **more stable** cation.",
    how:{ask:"Explain what drives a carbocation to rearrange.",
      know:"• Carbocation stability: **3° > 2° > 1° > methyl** (alkyl groups donate electron density).\n• **1,2-hydride or 1,2-methyl shift**: a group on the next carbon moves over with its bonding pair, moving C⁺ to that carbon.\n• Shifts happen when the new cation is more stable.",
      steps:[{text:"The shift turns a 2° cation into a 3° one.",hl:"a secondary carbocation shifts a hydride",fig:["cpt-shift-2","cpt-shift-3"]},
        {text:"A 2° cation is less stable than a 3°, so it would not form at the 3° cation's expense.",strike:["The 2° cation is more stable"]},
        {text:"The hydride moves within the ion; it does not leave. Bromide adds wherever the cation ends up.",strike:["Hydride is a good leaving group","Bromide prefers 2° carbons"]},
        {text:"Answer: the 3° cation is more stable."}],
      trap:"Thinking the nucleophile directs the shift; the cation rearranges first, driven only by its own stability."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"secondary carbocation",note:"less stable"},{t:"hydride",note:"H with its two electrons"},{t:"tertiary",note:"more stable"}]},
      {text:"**Rank cations.** More alkyl groups on C⁺ spread the charge.",calc:["3° > 2° > 1° > CH₃⁺"]},
      {text:"**Move downhill.** The H on the next carbon slides over with its electron pair, leaving C⁺ on the more substituted carbon."},
      {text:"**Rule to reuse:** a carbocation shifts H or CH₃ from a neighboring carbon whenever that makes a more stable cation."}]},
  {id:"cpt-pe1-07b",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5D",skill:"SIRS 2",from:["pe1-cp:7#2"],
    q:"3,3-Dimethylbutan-2-ol reacts with HBr. Which product can form without a methyl shift in the carbocation?",
    choices:["2-Bromo-3,3-dimethylbutane","2-Bromo-2,3-dimethylbutane","2,3-Dimethylbut-2-ene","2,3-Dimethylbut-1-ene"],ans:0,
    exp:"Loss of water from C2 leaves a **secondary cation on C2**. Br⁻ adding there gives **2-bromo-3,3-dimethylbutane** directly. C3 is quaternary (no H), so a **1,2-methyl shift** from C3 makes a 3° cation at C3; that cation gives 2-bromo-2,3-dimethylbutane, 2,3-dimethylbut-2-ene and 2,3-dimethylbut-1-ene.",
    how:{ask:"Find the product whose new group sits on the carbon that held the OH, with the carbon skeleton unchanged.",
      know:"• C⁺ forms where the OH was; Br⁻ there = direct product.\n• A methyl shift moves C⁺ to the next carbon and rearranges the skeleton (the methyl changes carbons).\n• Products with Br on a carbon that never held the OH, a C=C that does not include that carbon, or a changed branching pattern come from the shifted cation.",
      steps:[{text:"The OH is on C2; C3 carries two methyls and no H.",hl:"3,3-Dimethylbutan-2-ol"},
        {text:"Direct path: Br⁻ adds to C2, keeping both methyls on C3.",calc:["CH₃–CH(Br)–C(CH₃)₂–CH₃ = **2-bromo-3,3-dimethylbutane**"]},
        {text:"A 2,3-dimethyl skeleton means one methyl moved from C3 to C2.",strike:["2-Bromo-2,3-dimethylbutane","2,3-Dimethylbut-2-ene","2,3-Dimethylbut-1-ene"]},
        {text:"Answer: 2-bromo-3,3-dimethylbutane."}],
      trap:"Choosing an alkene because elimination seems \"direct\"; here every listed alkene has the 2,3-dimethyl skeleton of the shifted cation."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"3,3-Dimethylbutan-2-ol",note:"OH on C2, quaternary C3"},{t:"HBr",note:"cation path"},{t:"without a methyl shift",note:"direct product"}]},
      {text:"**Place the cation.** C⁺ forms on C2, where the OH was."},
      {text:"**Compare skeletons.** Before the shift: two methyls on C3. After: one on C2 and one on C3.",calc:["3,3-dimethyl → unshifted","2,3-dimethyl → shifted"]},
      {text:"**Pick the unshifted one.** Br on C2 with the 3,3-dimethyl skeleton."},
      {text:"**Rule to reuse:** a product whose groups or branches moved to a carbon that never held the OH came from a rearranged cation."}]},
  {id:"cpt-pe1-07c",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5D",skill:"SIRS 2",from:["pe1-cp:7#3"],
    q:"An alcohol reacts with HBr, and the product's Br sits on the carbon next to the one that held the OH. What does this most likely indicate?",
    choices:["A 1,2-shift occurred","Direct SN2 attack occurred","The alcohol was tertiary","Two bromides were added"],ans:0,
    exp:"Without rearrangement, Br⁻ bonds to the carbon that **held the OH** (where C⁺ formed, or where SN2 attack occurs). Br on the **neighboring** carbon means the positive charge moved there first by a **1,2-hydride or 1,2-methyl shift** (elimination followed by re-addition of HBr can give the same result, but a 1,2-shift is the usual cause).",
    how:{ask:"Decide what moved the reactive site off the original C–OH carbon.",
      know:"• Direct substitution (SN1 or SN2) puts Br on the carbon that held the OH.\n• A **1,2-shift** moves C⁺ to the next carbon, so Br ends up there.",
      steps:[{text:"The Br is one carbon away from where the OH was.",hl:"the carbon next to the one that held the OH"},
        {text:"SN2 puts Br exactly where the OH left.",strike:["Direct SN2 attack occurred"]},
        {text:"A tertiary alcohol or a second Br does not move the site of attack.",strike:["The alcohol was tertiary","Two bromides were added"]},
        {text:"Answer: a 1,2-shift occurred."}],
      trap:"Assuming the nucleophile can wander; Br⁻ bonds where the cation is, so a moved Br means a moved cation."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"carbon next to the one that held the OH",note:"group on a new carbon"}]},
      {text:"**Where should Br go?** Directly, it replaces the OH on the same carbon."},
      {text:"**Explain the move.** The cation shifted one carbon over before Br⁻ arrived.",calc:["C2⁺ → (H or CH₃ shift) → C3⁺ → C3–Br"]},
      {text:"**Rule to reuse:** a new group on a carbon that never held the leaving group is the fingerprint of a carbocation rearrangement."}]},
  // pe1-cp:8 (GC elution order follows volatility)
  {id:"cpt-pe1-08a",s:"Separations & Lab Techniques",disc:"organic_chem",aamc:"5C",skill:"SIRS 2",from:["pe1-cp:8#1"],
    q:"In gas chromatography with a nonpolar column, which compound in a mixture generally reaches the detector first?",
    choices:["The lowest-boiling","The highest-boiling","The most hydrogen-bonded","The most massive"],ans:0,
    exp:"In GC the sample is vaporized and carried by an inert gas. A compound that **stays in the gas phase** most (the most **volatile**, lowest boiling point) spends the least time dissolved in the column's liquid and **elutes first**.",
    how:{ask:"Link elution order in GC to volatility.",
      know:"• **GC**: mobile phase = carrier gas; stationary phase = a liquid film in the column.\n• Most volatile (lowest boiling point) → mostly in the gas → **elutes first**.\n• Boiling point rises with stronger intermolecular forces and larger size.",
      steps:[{text:"The carrier gas moves only the molecules that are in the vapor.",hl:"reaches the detector first"},
        {text:"High boiling point, strong hydrogen bonding and large mass all keep a compound in the column longer.",strike:["The highest-boiling","The most hydrogen-bonded","The most massive"]},
        {text:"Answer: the lowest-boiling compound."}],
      trap:"Picking by polarity or mass alone: on a nonpolar GC column, volatility (boiling point) sets the elution order."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"gas chromatography",note:"gas mobile phase"},{t:"first",note:"spends most time as gas"}]},
      {text:"**Only gas moves.** A molecule advances only while it is in the vapor."},
      {text:"**Volatile wins.** The lowest boiling point means the most time in the vapor.",calc:["low bp → elutes first","high bp → elutes last"]},
      {text:"**Rule to reuse:** in GC, compounds come off in order of increasing boiling point."}]},
  {id:"cpt-pe1-08b",s:"Molecular Structure & Intermolecular Forces",disc:"organic_chem",aamc:"5C",skill:"SIRS 2",from:["pe1-cp:8#2"],
    q:"Which of these three-carbon compounds has the lowest boiling point?",
    choices:["Propane","Propanal","Propan-1-ol","1-Chloropropane"],ans:0,
    exp:"Propane (44 g/mol) has only **London dispersion forces** and the smallest mass. Propanal and 1-chloropropane add **dipole–dipole** forces, and propan-1-ol adds **hydrogen bonding**, so propane boils lowest (about −42 °C).",
    how:{ask:"Rank the compounds by their strongest intermolecular force, then by size.",
      know:"• Intermolecular forces: **London < dipole–dipole < hydrogen bonding**.\n• London forces grow with molar mass and surface area.\n• Weakest forces → lowest boiling point → most volatile.",
      steps:[{text:"All four have three carbons, so their functional groups decide.",hl:"three-carbon compounds"},
        {text:"Strongest force in each.",calc:["propane: London only","propanal: dipole–dipole","1-chloropropane: dipole–dipole","propan-1-ol: **hydrogen bonding**"]},
        {text:"Each polar compound has stronger forces than the alkane.",strike:["Propanal","Propan-1-ol","1-Chloropropane"]},
        {text:"Answer: propane."}],
      trap:"Thinking 1-chloropropane boils lowest because it cannot hydrogen bond: its dipole and larger mass (78.5 vs 44 g/mol) put it near 47 °C, far above propane."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"three-carbon",note:"similar size"},{t:"lowest boiling point",note:"weakest forces"}]},
      {text:"**Name each force.** Alkane: London. C=O or C–Cl: dipole–dipole. O–H: hydrogen bonding."},
      {text:"**Weakest boils first.**",calc:["propane < propanal ≈ 1-chloropropane < propan-1-ol"]},
      {text:"**Rule to reuse:** with similar sizes, an alkane boils lowest and an alcohol highest, because hydrogen bonding is the strongest force."}]},
  {id:"cpt-pe1-08c",s:"Molecular Structure & Intermolecular Forces",disc:"organic_chem",aamc:"5C",skill:"SIRS 2",from:["pe1-cp:8#3"],
    q:"Pentan-1-ol boils about 100 °C higher than pentane. Which intermolecular force accounts for most of this difference?",
    choices:["Hydrogen bonding","London dispersion","Ion–dipole attraction","Covalent bonding"],ans:0,
    exp:"Both molecules have five carbons, so their **London** forces are similar. The O–H group of pentan-1-ol lets its molecules **hydrogen bond** to each other, the strongest intermolecular force between neutral molecules, which raises the boiling point most.",
    how:{ask:"Find the force the alcohol has that the alkane lacks.",
      know:"• **Hydrogen bonding** (O–H, N–H, F–H with a lone pair on N, O or F) is the strongest force between neutral molecules.\n• Ion–dipole forces need ions; covalent bonds are within molecules, not between them.",
      steps:[{text:"Same carbon count, so the difference comes from the –OH group.",hl:"Pentan-1-ol"},
        {text:"London forces are about equal for the two molecules.",strike:["London dispersion"]},
        {text:"There are no ions, and boiling does not break covalent bonds.",strike:["Ion–dipole attraction","Covalent bonding"]},
        {text:"Answer: hydrogen bonding."}],
      trap:"Choosing covalent bonding: boiling separates molecules; it does not break bonds inside them."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"Pentan-1-ol",note:"has O–H"},{t:"pentane",note:"London only"},{t:"100 °C higher",note:"a big force difference"}]},
      {text:"**Cancel what is shared.** Both have five carbons, so their London forces are similar."},
      {text:"**Find what is new.** The O–H group lets alcohol molecules hydrogen bond to each other."},
      {text:"**Rule to reuse:** an O–H or N–H group raises the boiling point far more than added mass does, because of hydrogen bonding."}]},
  {id:"cpt-pe1-08d",s:"Separations & Lab Techniques",disc:"organic_chem",aamc:"5C",skill:"SIRS 2",from:["pe1-cp:8#3"],
    q:"A mixture of pent-1-ene, 1-chloropentane and pentan-1-ol is run on a nonpolar gas chromatography column. In what order do they reach the detector?",
    choices:["Alkene, then chloride, then alcohol","Alcohol, then chloride, then alkene","Chloride, then alkene, then alcohol","Alkene, then alcohol, then chloride"],ans:0,
    exp:"Lowest boiling point first. Pent-1-ene has only London forces (bp ≈ 30 °C). 1-Chloropentane adds a C–Cl dipole and more mass (bp ≈ 108 °C). Pentan-1-ol **hydrogen-bonds** (bp ≈ 138 °C), so it comes out **last**.",
    how:{ask:"Rank the three by intermolecular forces, which sets their boiling points and so their GC order.",
      know:"• GC elutes in order of increasing boiling point.\n• Alkene: London only → most volatile.\n• Alkyl halide: dipole–dipole plus London → middle.\n• Alcohol: hydrogen bonding → least volatile, last.",
      steps:[{text:"All three have five carbons, so the functional group decides.",hl:"pent-1-ene, 1-chloropentane and pentan-1-ol",calc:["pent-1-ene: London → bp ≈ 30 °C","1-chloropentane: dipole → bp ≈ 108 °C","pentan-1-ol: H-bonding → bp ≈ 138 °C"]},
        {text:"The alcohol hydrogen-bonds, so it cannot come out first or second.",strike:["Alcohol, then chloride, then alkene","Alkene, then alcohol, then chloride"]},
        {text:"The alkene is more volatile than the chloride, so it comes out before it.",strike:["Chloride, then alkene, then alcohol"]},
        {text:"Answer: alkene, then chloride, then alcohol."}],
      trap:"Ordering by molar mass alone: the alcohol is lighter than the chloride but comes out after it, because it hydrogen-bonds."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"nonpolar gas chromatography column",note:"order by boiling point"},{t:"reach the detector",note:"elution order"}]},
      {text:"**Name each force.** C=C: London only. C–Cl: a dipole. O–H: hydrogen bonding."},
      {text:"**Weakest forces leave first.**",calc:["alkene < alkyl halide < alcohol"]},
      {text:"**Rule to reuse:** in GC, an alkene beats an alkyl halide of the same chain, and an alcohol, which hydrogen-bonds, comes out last."}]},
  // pe1-cp:9 (rate law → SN2 → inversion, and the R/S label)
  {id:"cpt-pe1-09b",s:"Stereochemistry",disc:"organic_chem",aamc:"5B",skill:"SIRS 2",from:["pe1-cp:9#1","pe1-cp:9#2"],
    q:"(R)-2-Chlorobutane reacts by SN2 with sodium methanethiolate, CH₃SNa. What configuration does the product have?",
    choices:["(S) only","(R) only","Racemic mixture","Meso compound"],ans:0,
    exp:"SN2 gives **inversion**. The –SCH₃ group (first atom S, 16) now ranks **first**, just as Cl did, and the order of the others (ethyl > methyl > H) is unchanged. Inverting the 3D arrangement with the same priority order flips the label: **R → S**.",
    how:{ask:"Apply inversion, then check whether the priorities changed.",
      know:"• **SN2 → inversion** of the 3D arrangement; no carbocation, so no racemization.\n• **CIP priority** by atomic number of the first atom: S (16) and Cl (17) both outrank C (6) and H (1).\n• If the new group has the same rank as the old one, inversion switches R ↔ S.",
      steps:[{text:"The reaction is SN2, so the configuration inverts.",hl:"reacts by SN2",fig:"cpt-sn2-backside"},
        {text:"Priorities before and after.",calc:["before: Cl > ethyl > methyl > H","after: **SCH₃** > ethyl > methyl > H"]},
        {text:"Same order, inverted geometry, so the label changes; SN2 does not racemize, and the product has one stereocenter.",strike:["(R) only","Racemic mixture","Meso compound"]},
        {text:"Answer: (S) only."}],
      trap:"Keeping the label R: inversion with unchanged priorities always switches the descriptor."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"(R)-2-Chlorobutane",note:"starting label"},{t:"SN2",note:"inversion"},{t:"CH₃SNa",note:"S nucleophile"}]},
      {text:"**Flip the umbrella.** The nucleophile enters opposite Cl; the other three groups turn inside out."},
      {text:"**Re-rank.** S still outranks every carbon, just as Cl did.",calc:["rank order unchanged → R becomes S"]},
      {text:"**Rule to reuse:** SN2 inverts the center; if the entering group takes the leaving group's priority rank, R and S swap."}]},
  {id:"cpt-pe1-09c",s:"Stereochemistry",disc:"organic_chem",aamc:"5B",skill:"SIRS 2",from:["pe1-cp:9#2"],
    q:"Which substituent on a stereocenter has the highest Cahn–Ingold–Prelog priority?",
    choices:["–SH","–OH","–NH₂","–CH₂Br"],ans:0,
    exp:"CIP priority is decided by the **atomic number of the first atom**: S (16) > O (8) > N (7) > C (6). The bromine in –CH₂Br is one atom farther out, so it does not count until the first atoms tie.",
    how:{ask:"Compare only the atoms bonded directly to the stereocenter.",
      know:"• **CIP rule 1**: higher atomic number of the first atom = higher priority.\n• Look farther out only when the first atoms are the same.\n• S 16, O 8, N 7, C 6, H 1.",
      steps:[{text:"First atoms: S, O, N and C.",hl:"highest Cahn–Ingold–Prelog priority"},
        {text:"O, N and the carbon of –CH₂Br all have lower atomic numbers than S; Br is not the first atom.",strike:["–OH","–NH₂","–CH₂Br"]},
        {text:"Answer: –SH."}],
      trap:"Ranking –CH₂Br first because Br is heavy; priority is decided at the first atom, which is carbon."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"highest Cahn–Ingold–Prelog priority",note:"compare first atoms"}]},
      {text:"**List the first atoms.**",calc:["–SH: S (16)","–OH: O (8)","–NH₂: N (7)","–CH₂Br: C (6)"]},
      {text:"**Highest atomic number wins.** S beats the rest."},
      {text:"**Rule to reuse:** CIP priority is set by the first atom's atomic number; go farther out only to break a tie."}]},
  {id:"cpt-pe1-09e",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5B",skill:"SIRS 2",from:["pe1-cp:9#3"],
    q:"3-Bromohexane reacts with sodium hydrosulfide, NaSH, by SN2. What is the name of the substitution product?",
    choices:["Hexane-3-thiol","Pentane-3-thiol","Hexane-1-thiol","Heptane-3-thiol"],ans:0,
    exp:"SN2 swaps the leaving group for the nucleophile **on the same carbon** and changes no C–C bond. The chain keeps its **6 carbons** and the SH lands on **C3**, where Br was: **hexane-3-thiol**.",
    how:{ask:"Count the product's carbon chain and locate the new group.",
      know:"• Substitution replaces X with Nu on the **same carbon**; no carbons are added or removed (HS⁻ brings no carbon).\n• Name: chain length (hex = 6) + position + suffix (-thiol for SH).\n• Number the chain so the group gets the lowest locant.",
      steps:[{text:"The substrate's chain and the leaving group's position.",hl:"3-Bromohexane",calc:["hexane = **6 carbons**","Br on **C3**"]},
        {text:"HS⁻ replaces Br on C3; the chain is untouched.",calc:["C₆ chain, SH on C3 → **hexane-3-thiol**"]},
        {text:"Five or seven carbons would mean a carbon was lost or gained, which SN2 with HS⁻ cannot do.",strike:["Pentane-3-thiol","Heptane-3-thiol"]},
        {text:"SN2 does not move the group to the chain's end.",strike:["Hexane-1-thiol"]},
        {text:"Answer: hexane-3-thiol."}],
      trap:"Miscounting the chain after drawing the product: the nucleophile replaces one atom, so the carbon count stays the same."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"3-Bromohexane",note:"6 C, Br on C3"},{t:"NaSH",note:"HS⁻, no carbon"},{t:"SN2",note:"same carbon"}]},
      {text:"**Count the chain.** Hex- means 6 carbons, and nothing in HS⁻ adds a carbon."},
      {text:"**Keep the position.** SN2 puts the new group where the leaving group was.",calc:["Br on C3 → SH on C3"]},
      {text:"**Name it.**",calc:["hexane + 3 + thiol → hexane-3-thiol"]},
      {text:"**Rule to reuse:** after a substitution, the product keeps the substrate's carbon chain and the new group's position; only the group's name changes."}]},
  // pe1-cp:10 (Fischer esterification: the alcohol oxygen stays in the ester)
  {id:"cpt-pe1-10a",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5D",skill:"SIRS 3",from:["pe1-cp:10#1"],
    q:"In the acid-catalyzed esterification of acetic acid with ethanol, the oxygen joining the acyl carbon to the ethyl group comes from:",
    choices:["the ethanol","the acetic acid","the acid catalyst","the water"],ans:0,
    exp:"In Fischer esterification the **alcohol's oxygen is the nucleophile**: it attacks the protonated carbonyl carbon. Later an –OH from the **acid** leaves as water. So the bridging –O– of ethyl acetate is the **ethanol** oxygen.",
    how:{ask:"Identify the nucleophile, whose oxygen is kept in the product.",
      know:"• **Fischer esterification**: RCOOH + R′OH ⇌ RCOOR′ + H₂O (acid catalyst).\n• The **alcohol O attacks** the carbonyl carbon; **water leaves from the acid** side.\n• So the ester's C–O–R′ oxygen comes from the alcohol.",
      steps:[{text:"The bridging oxygen links the acyl carbon to the ethyl group.",hl:"the oxygen joining the acyl carbon to the ethyl group"},
        {text:"The acid loses one of its oxygens as water; the catalyst only adds and removes H⁺.",strike:["the acetic acid","the acid catalyst","the water"]},
        {text:"Answer: the ethanol."}],
      trap:"Assuming the acid keeps both oxygens; one of them leaves in the water."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"acid-catalyzed esterification",note:"Fischer"},{t:"ethanol",note:"the nucleophile"}]},
      {text:"**Activate.** H⁺ protonates the acid's C=O, making the carbon more electrophilic."},
      {text:"**Attack and leave.**",calc:["EtO–H attacks C → tetrahedral intermediate","acid's –OH → –OH₂⁺ → leaves as H₂O"]},
      {text:"**Rule to reuse:** in Fischer esterification the alcohol keeps its oxygen as the ester's –O–, and the acid loses an oxygen as water."}]},
  {id:"cpt-pe1-10b",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5D",skill:"SIRS 3",from:["pe1-cp:10#2"],
    q:"Propanoic acid with ¹⁸O in both of its oxygens is esterified with unlabeled ethanol under acid catalysis. Which ester oxygen carries no label?",
    choices:["The bridging O","The carbonyl O","Both oxygens","Neither oxygen"],ans:0,
    exp:"The **ethanol oxygen** (unlabeled) attacks the protonated carbonyl carbon and stays bonded to the ethyl group as the ester's **bridging –O–**. One labeled acid oxygen leaves in the water; the other labeled oxygen stays as the ester's **C=O**. So only the bridging oxygen is unlabeled.",
    how:{ask:"Follow each oxygen through the mechanism: which one does the ester get from the alcohol?",
      know:"• Fischer esterification: the **alcohol O attacks** the carbonyl carbon and becomes the ester's –O–R′.\n• One of the acid's oxygens leaves as **water**; the other stays as the ester's **C=O**.\n• An isotope label marks an atom; where it ends up shows which bonds broke.",
      steps:[{text:"The label is on the acid's oxygens; the ethanol oxygen is ordinary.",hl:"¹⁸O in both of its oxygens"},
        {text:"Map each oxygen.",calc:["ester C=O: from the acid → **¹⁸O**","ester –O–: from ethanol → **¹⁶O**","water: from the acid → ¹⁸O"]},
        {text:"The carbonyl O is labeled, so neither \"both\" nor the carbonyl is unlabeled; the bridging O is unlabeled, so \"neither\" fails.",strike:["The carbonyl O","Both oxygens","Neither oxygen"]},
        {text:"Answer: the bridging O."}],
      trap:"Assuming the acid supplies the bridging oxygen; that oxygen comes from the alcohol, and an acid oxygen leaves as water."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"¹⁸O in both of its oxygens",note:"label on the acid"},{t:"unlabeled ethanol",note:"ordinary O nucleophile"},{t:"carries no label",note:"find the alcohol's O"}]},
      {text:"**The alcohol keeps its oxygen.** Ethanol's O attacks the carbonyl carbon and ends up between C=O and the ethyl group."},
      {text:"**The acid gives one O to water and keeps one as C=O.**",calc:["C=¹⁸O stays","–¹⁸OH leaves as H₂¹⁸O","–¹⁶O–Et from ethanol"]},
      {text:"**Rule to reuse:** in Fischer esterification the ester's bridging oxygen comes from the alcohol, its C=O oxygen from the acid, and the water from the acid."}]},
  {id:"cpt-pe1-10d",s:"Reaction Mechanisms",disc:"organic_chem",aamc:"5D",skill:"SIRS 3",from:["pe1-cp:10#3"],
    q:"To learn which reactant loses its –OH in an acid-catalyzed esterification, a chemist replaces the alcohol's O–H hydrogen with deuterium. Why does this label fail?",
    choices:["Acidic H exchanges with solvent","Deuterium is too heavy to react","The ester cannot contain hydrogen","Mass spectrometry cannot detect D"],ans:0,
    exp:"A hydrogen on oxygen is **acidic**: in acid it is swapped on and off rapidly with the solvent and the catalyst, so the D is **scrambled** among all O–H groups before and during the reaction. Where it ends up says nothing about which bond broke.",
    how:{ask:"Decide whether the labeled atom stays put long enough to report which bond broke.",
      know:"• H on O or N is acidic and **exchanges** with protic solvent and acid quickly.\n• A useful label must sit on an atom that does not exchange.",
      steps:[{text:"The label is on an O–H hydrogen.",hl:"replaces the alcohol's O–H hydrogen with deuterium"},
        {text:"That H trades places with the solvent's H in acid, so the label spreads everywhere.",calc:["R–O–D + H₂O ⇌ R–O–H + HOD"]},
        {text:"Deuterium reacts normally, the ester does contain H atoms, and mass spectrometry detects D easily.",strike:["Deuterium is too heavy to react","The ester cannot contain hydrogen","Mass spectrometry cannot detect D"]},
        {text:"Answer: the acidic H exchanges with solvent."}],
      trap:"Assuming any isotope tracks its atom: a label on an exchangeable H is lost to the solvent."},
    teach:[{text:"First, **find the key words**.",marks:[{t:"O–H hydrogen",note:"acidic, exchangeable"},{t:"deuterium",note:"the label"}]},
      {text:"**Ask if the label stays put.** O–H hydrogens hop between molecules in acid many times a second."},
      {text:"**Scrambled label, no answer.**",calc:["D spreads over every O–H → no information"]},
      {text:"**Rule to reuse:** an H on O or N is a useless label: it exchanges in acid, so it cannot show which bond broke."}]},
];
